const fs=require('node:fs'),os=require('node:os'),path=require('node:path'),assert=require('node:assert/strict'),{spawn}=require('node:child_process');
const profile=fs.mkdtempSync(path.join(os.tmpdir(),'gnci-footer-'));
const browser=spawn('C:/Program Files/Google/Chrome/Application/chrome.exe',['--headless=new','--disable-gpu','--no-first-run','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{windowsHide:true,stdio:'ignore'});
const delay=ms=>new Promise(r=>setTimeout(r,ms));let socket;
async function until(fn){for(let end=Date.now()+30000;Date.now()<end;){if(await fn())return;await delay(100);}throw Error('Browser readiness timed out');}
(async()=>{
await until(()=>fs.existsSync(path.join(profile,'DevToolsActivePort')));const port=fs.readFileSync(path.join(profile,'DevToolsActivePort'),'utf8').split('\n')[0];const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();socket=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>socket.addEventListener('open',r,{once:true}));
let serial=0;const pending=new Map();socket.addEventListener('message',e=>{const p=JSON.parse(e.data);if(pending.has(p.id)){pending.get(p.id)(p);pending.delete(p.id);}});const send=(method,params={})=>new Promise((resolve,reject)=>{const id=++serial;pending.set(id,p=>p.error?reject(Error(JSON.stringify(p.error))):resolve(p.result));socket.send(JSON.stringify({id,method,params}));});const evaluate=async expression=>{const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;};
await send('Page.enable');await send('Page.addScriptToEvaluateOnNewDocument',{source:"try{sessionStorage.setItem('gncIntroSeen','1')}catch(_){}"});await send('Network.enable');await send('Network.setBlockedURLs',{urls:['*fonts.googleapis.com*','*fonts.gstatic.com*','*facebook.com*','*youtube.com*','*maps.google.com*']});
for(const route of ['/','/pages/about/gnc-history.php','/pages/admission/tuition-fees.php']){
await send('Page.navigate',{url:'http://localhost:8080'+route});await until(()=>evaluate('document.readyState==="complete"&&!!document.querySelector(".gnc-footer-grid")'));await until(()=>evaluate('document.querySelector("#gncFooterSuggestionLinks")?.children.length>0'));assert(await evaluate('document.querySelector("#gncFooterSuggestions").compareDocumentPosition(document.querySelector(".gnc-footer-grid"))&Node.DOCUMENT_POSITION_FOLLOWING'));await evaluate('document.querySelector(".gnc-footer").scrollIntoView()');
for(const width of [1440,820,390]){await send('Emulation.setDeviceMetricsOverride',{width,height:1000,deviceScaleFactor:1,mobile:false});await delay(150);const metrics=await evaluate(`(()=>{const f=document.querySelector('.gnc-footer'),g=f.querySelector('.gnc-footer-grid'),r=f.getBoundingClientRect();return {columns:getComputedStyle(g).gridTemplateColumns.split(' ').length,overflow:f.scrollWidth>innerWidth+1,links:f.querySelectorAll('a').length,frames:f.querySelectorAll('iframe').length,logo:!!f.querySelector('.gnc-footer-seal'),rect:{x:0,y:Math.max(0,r.top+scrollY),width:innerWidth,height:Math.ceil(r.height)}}})()`);assert(!metrics.overflow,'Footer overflow '+route+' '+width);assert.equal(metrics.columns,width===1440?3:width===820?2:1);assert(metrics.links>10&&metrics.frames===1&&!metrics.logo);if(route==='/'&&width!==820){const shot=await send('Page.captureScreenshot',{format:'png',captureBeyondViewport:true,clip:{...metrics.rect,scale:1}});fs.writeFileSync('cache/footer-design-'+width+'.png',Buffer.from(shot.data,'base64'));}console.log('PASS footer:',route,width,metrics.columns,'columns');}
}
})().catch(e=>{console.error(e);process.exitCode=1;}).finally(async()=>{if(socket)socket.close();browser.kill();await delay(600);if(path.dirname(profile)===os.tmpdir()&&path.basename(profile).startsWith('gnci-footer-'))try{fs.rmSync(profile,{recursive:true,force:true,maxRetries:3,retryDelay:200});}catch{}});
